-- ============================================
-- LUMA — Thème 17 : 3e scénario COURT x4 — Une blessure mineure à l'entraînement
-- ============================================


update scenarios set content = '{"characters": {"coach": "l''entraîneur", "physio": "le kinésithérapeute"}, "start_node": "n1", "nodes": {"n1": {"speaker": "coach", "text": "Are you okay? That looked like a hard fall.", "text_fr": "Ça va ? Ça avait l''air d''une chute difficile.", "choices": [{"text": "I''m fine, just twisted my ankle a little.", "text_fr": "Ça va, j''ai juste un peu tordu ma cheville.", "next": "n2"}, {"text": "It hurts more than I expected, actually.", "text_fr": "Ça fait plus mal que prévu, en fait.", "next": "n2b"}]}, "n2": {"speaker": "coach", "text": "Let''s ice it just in case, better safe than sorry.", "text_fr": "Mettons de la glace au cas où, mieux vaut prévenir que guérir.", "choices": [{"text": "Good idea, thanks for checking on me.", "text_fr": "Bonne idée, merci de t''inquiéter pour moi.", "next": "n3"}]}, "n2b": {"speaker": "coach", "text": "Let''s get that looked at by our physio right away.", "text_fr": "Faisons vérifier ça par notre kiné tout de suite.", "choices": [{"text": "Okay, better to be careful.", "text_fr": "D''accord, mieux vaut être prudent.", "next": "n3"}]}, "n3": {"speaker": "physio", "text": "Let''s see how it moves. Any sharp pain, or just soreness?", "text_fr": "Voyons comment ça bouge. Une douleur aiguë, ou juste une gêne ?", "choices": [{"text": "Mostly soreness, it''s not too sharp.", "text_fr": "Surtout une gêne, c''est pas trop aigu.", "next": "n4"}, {"text": "There''s a sharp pain when I rotate it a certain way.", "text_fr": "Il y a une douleur aiguë quand je la tourne d''une certaine façon.", "next": "n4"}]}, "n4": {"speaker": "physio", "text": "That sounds like a mild sprain. Rest for a few days and you should be fine.", "text_fr": "Ça ressemble à une entorse légère. Reposez-vous quelques jours et vous devriez aller bien.", "choices": [{"text": "That''s a relief, thank you for checking.", "text_fr": "Ça soulage, merci d''avoir vérifié.", "next": "n5"}]}, "n5": {"speaker": "coach", "text": "Take it easy for the rest of the week, we don''t want this getting worse.", "text_fr": "Prends ça tranquille pour le reste de la semaine, on veut pas que ça empire.", "choices": [{"text": "Understood, I''ll sit out the next few sessions.", "text_fr": "Compris, je vais manquer les prochaines séances.", "next": "end_checked"}]}, "end_checked": {"speaker": "coach", "text": "Good call getting it checked, health comes first.", "text_fr": "Bien joué de faire vérifier ça, la santé passe avant tout.", "end": true, "ending_label": "Petite blessure prise au sérieux et bien gérée 🩹⚽"}}}'::jsonb, is_playable = true
where title = 'Une blessure mineure à l''''entraînement'
